// Original analytic-gradient PINN implementation. No external ML dependency.
const K=2*Math.PI, H=32, SIZE=1+5*H;
export function rng(seed){let s=seed>>>0;return()=>{s+=0x6D2B79F5;let t=s;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
export function exact(x,t){return .5+.4*Math.exp(-K*K*.01*t)*Math.sin(K*(x-.5*t));}
export function validateConfig(p){if(!p||!Number.isInteger(p.samples)||p.samples<4||p.samples>64||!Number.isInteger(p.steps)||p.steps<100||p.steps>5000||!Number.isInteger(p.seed)||p.seed<1||p.seed>9999||!Number.isFinite(p.weight)||p.weight<0||p.weight>10||!Number.isFinite(p.noise)||p.noise<0||p.noise>.1)throw Error('Choose valid training settings within the displayed ranges.');return p;}
export function createModel(seed){const random=rng(seed);const p=new Float64Array(SIZE);p[0]=.5;for(let j=0;j<H;j++){let i=1+5*j;p[i]=(random()-.5)*.2;for(let k=1;k<5;k++)p[i+k]=(random()-.5)*2;}return {p,m:new Float64Array(SIZE),v:new Float64Array(SIZE),iteration:0};}
export function evaluate(p,x,t,derivatives=false){let u=p[0],r=0;const gu=derivatives?new Float64Array(SIZE):null,gr=derivatives?new Float64Array(SIZE):null;if(gu)gu[0]=1;const sn=Math.sin(K*x),cs=Math.cos(K*x),tm=2*t-1;
 for(let j=0;j<H;j++){const i=1+5*j,w=p[i],A=p[i+1],B=p[i+2],C=p[i+3],E=p[i+4];const z=A*sn+B*cs+C*tm+E,h=Math.tanh(z),s=1-h*h,zx=K*(A*cs-B*sn),zxx=-K*K*(A*sn+B*cs),q=2*C+.5*zx-.01*zxx,R=s*q+.02*h*s*zx*zx;u+=w*h;r+=w*R;
 if(gu){gu[i]=h;gu[i+1]=w*s*sn;gu[i+2]=w*s*cs;gu[i+3]=w*s*tm;gu[i+4]=w*s;
 const rz=w*(-2*h*s*q+.02*(s*s-2*h*h*s)*zx*zx),rx=w*(.5*s+.04*h*s*zx),rxx=-.01*w*s;gr[i]=R;gr[i+1]=rz*sn+rx*K*cs-rxx*K*K*sn;gr[i+2]=rz*cs-rx*K*sn-rxx*K*K*cs;gr[i+3]=rz*tm+2*w*s;gr[i+4]=rz;}}
 return{u,r,gu,gr};}
export function dataset(config){const random=rng(config.seed+1000);const obs=Array.from({length:config.samples},()=>{const x=random(),t=random()*.25;return{x,t,y:exact(x,t)+config.noise*(random()+random()+random()+random()+random()+random()-3)*Math.sqrt(2)};});const ic=Array.from({length:32},(_,i)=>({x:(i+.5)/32,t:0,y:exact((i+.5)/32,0)}));return{obs,ic};}
export function loss(p,data,points,weight,gradient=true){const g=new Float64Array(SIZE);let ld=0,li=0,lp=0;
 for(const [items,key] of [[data.obs,'data'],[data.ic,'ic']])for(const pt of items){const e=evaluate(p,pt.x,pt.t,gradient),d=e.u-pt.y;if(key==='data')ld+=d*d/items.length;else li+=d*d/items.length;if(gradient)for(let i=0;i<SIZE;i++)g[i]+=2*d/items.length*e.gu[i];}
 for(const pt of points){const e=evaluate(p,pt.x,pt.t,gradient&&weight>0);lp+=e.r*e.r/points.length;if(gradient&&weight>0)for(let i=0;i<SIZE;i++)g[i]+=weight*2*e.r/points.length*e.gr[i];}
 return{data:ld,initial:li,physics:lp,total:ld+li+weight*lp,g};}
function adam(model,g){const n=++model.iteration,b1=1-.9**n,b2=1-.999**n;for(let i=0;i<SIZE;i++){model.m[i]=.9*model.m[i]+.1*g[i];model.v[i]=.999*model.v[i]+.001*g[i]*g[i];model.p[i]-=.003*(model.m[i]/b1)/(Math.sqrt(model.v[i]/b2)+1e-8);}}
export function createExperiment(config){validateConfig(config);const data=dataset(config),random=rng(config.seed+2000);return{config,data,random,nn:createModel(config.seed),pinn:createModel(config.seed),step:0,nnMs:0,pinnMs:0};}
export function trainStep(ex){const pts=Array.from({length:48},()=>({x:ex.random(),t:ex.random()}));let start=performance.now();const n=loss(ex.nn.p,ex.data,pts,0);adam(ex.nn,n.g);ex.nnMs+=performance.now()-start;start=performance.now();const p=loss(ex.pinn.p,ex.data,pts,ex.config.weight);adam(ex.pinn,p.g);ex.pinnMs+=performance.now()-start;ex.step++;}
export function snapshot(ex){const points=Array.from({length:256},(_,i)=>({x:((i%16)+.5)/16,t:(Math.floor(i/16)+.5)/16}));const report=model=>{let error=0,held=0,nheld=0,drift=0;const field=[],residual=[];for(let ti=0;ti<=20;ti++){let mass=0;for(let xi=0;xi<64;xi++){const x=(xi+.5)/64,t=ti/20,e=evaluate(model.p,x,t);field.push(e.u);residual.push(e.r);mass+=e.u/64;const d=(e.u-exact(x,t))**2;error+=d;if(t>.25){held+=d;nheld++;}}drift=Math.max(drift,Math.abs(mass-.5));}const l=loss(model.p,ex.data,points,model===ex.nn?0:ex.config.weight,false);delete l.g;return{field,residual,l,rmse:Math.sqrt(error/field.length),heldRMSE:Math.sqrt(held/nheld),massDrift:drift};};return{step:ex.step,config:ex.config,observations:ex.data.obs,nn:report(ex.nn),pinn:report(ex.pinn),nnMs:ex.nnMs,pinnMs:ex.pinnMs};}
